harness.enable:
window.__generateLabelsPrev = [];
const rules = Object.keys(m.axeHandlers);
const results = await axe.run({
  runOnly: { type: 'rule', values: rules }
});
for (const violation of results.violations) {
  const handler = m.axeHandlers[violation.id];
  if (!handler) continue;
  for (const node of violation.nodes) {
    let el;
    try {
      el = document.querySelector(node.target[0]);
    } catch (e) {
      continue;
    }
    if (!el) continue;
    window.__generateLabelsPrev.push({
      el,
      hadAriaLabel: el.hasAttribute('aria-label'),
      ariaLabel: el.getAttribute('aria-label'),
      hadTitle: el.hasAttribute('title'),
      title: el.getAttribute('title'),
      processed: el.dataset.ai4a11yProcessed,
    });
    try {
      await handler(el);
    } catch (err) {
      console.error('Handler error:', err);
    }
  }
}

harness.disable:
if (window.__generateLabelsPrev) {
  for (const item of window.__generateLabelsPrev) {
    if (item.hadAriaLabel) item.el.setAttribute('aria-label', item.ariaLabel);
    else item.el.removeAttribute('aria-label');
    if (item.hadTitle) item.el.setAttribute('title', item.title);
    else item.el.removeAttribute('title');
    if (item.processed !== undefined) item.el.dataset.ai4a11yProcessed = item.processed;
    else delete item.el.dataset.ai4a11yProcessed;
  }
  delete window.__generateLabelsPrev;
}
document.querySelectorAll('[data-ai4a11y-processed]').forEach(el => {
  delete el.dataset.ai4a11yProcessed;
});
